// TestGenerateContractManifest is an explicit, deterministic fixture
// generator. Ordinary test runs skip it; P1/P17 invoke it against temporary
// schema trees generated by the exact Codex binary and the separately pinned
// source exports.
func TestGenerateContractManifest(t *testing.T) {
	if os.Getenv("CODEX_CONTRACT_GENERATE") != "1" {
		t.Skip("set CODEX_CONTRACT_GENERATE=1 to refresh exact-version fixtures")
	}
	in := readGeneratorInputs(t)

	stable, stableDocs := readGeneratedSurface(t, in.installedStable)
	experimental, experimentalDocs := readGeneratedSurface(t, in.installedExpUnfl)

	// The notification split (MADR 0163 D4, persisted by MADR 0236 D3.3).
	//
	// Codex's exporter never prunes experimental notifications, so both bundles
	// list every notification while the runtime suppresses the experimental ones.
	// The captured surfaces stay faithful to the exporter, because filtering them
	// in place makes the manifest disagree with the export it mirrors and breaks
	// the drift gate's exact mode. The split is kept beside them instead, as the
	// manifest's own field, which is what schema_version 2 made room for.
	experimentalOnly := experimentalNotifications(t, in.sourceTree)
	total := len(experimental.ServerNotifications)
	stableOnly := len(stableNotificationsOnly(stable.ServerNotifications, experimentalOnly))
	t.Logf("notifications: %d declared; %d stable, %d experimental-only by the source markers "+
		"(the captured surface records all %d, as the exporter emits them)",
		total, stableOnly, total-stableOnly, total)

	manifest := ContractManifest{
		SchemaVersion:             manifestSchemaVersion,
		CodexVersion:              in.version,
		BinarySHA256:              in.binarySHA256,
		Stable:                    stable,
		Experimental:              experimental,
		ExperimentalNotifications: declaredExperimentalNotifications(t, experimental, experimentalOnly),
		SchemaProperties:          schemaPropertyNames(stableDocs, experimentalDocs),
	}
	if got := len(manifest.ExperimentalNotifications); got != total-stableOnly {
		t.Fatalf("manifest records %d experimental notifications, the scan reported %d", got, total-stableOnly)
	}
	responses := sourceResponseTypes(t, in.sourceTree)
	checkSourceResponseTypes(t, responses, experimental, experimentalDocs)
	manifest.Capabilities = generatedCapabilities(stable, experimental)
	manifest.Fixtures = generatedFixtures(stable, experimental, stableDocs, experimentalDocs, responses)
	if err := manifest.Validate(); err != nil {
		t.Fatalf("generated manifest: %v", err)
	}

	sourceStableSurface, _ := readGeneratedSurface(t, in.sourceStable)
	sourceExperimentalSurface, _ := readGeneratedSurface(t, in.sourceExp)
	watch := SourceWatchManifest{
		SchemaVersion:  manifestSchemaVersion,
		Commit:         in.sourceCommit,
		Stable:         sourceStableSurface,
		Experimental:   sourceExperimentalSurface,
		InstalledDelta: sourceOnlyDelta(stable, experimental, sourceStableSurface, sourceExperimentalSurface),

		MCPApprovalMetaKeys: mcpApprovalMetaKeys(t, in.sourceTree),
	}

	fixtures := manifest.Fixtures
	manifest.Fixtures = nil
	if err := os.MkdirAll(in.outDir, 0o755); err != nil {
		t.Fatal(err)
	}
	writeGeneratedJSON(t, filepath.Join(in.outDir, "manifest.json"), manifest)
	writeGeneratedJSON(t, filepath.Join(in.outDir, "fixtures.json"), fixtures)
	writeGeneratedJSON(t, filepath.Join(in.outDir, "source-watch-manifest.json"), watch)
}

type generatedSchemaDocs struct {
	definitions map[string]struct {
		Required []string `json:"required"`
	}
	// properties is every property name declared anywhere in the export.
	properties map[string]struct{}
}

func readGeneratedSurface(t *testing.T, schemaPath string) (ContractSurface, generatedSchemaDocs) {
	t.Helper()
	raw, err := os.ReadFile(schemaPath)
	if err != nil {
		t.Fatal(err)
	}
	requests, err := parseSchemaMethods(raw, "ClientRequest")
	if err != nil {
		t.Fatal(err)
	}
	notifications, err := parseSchemaMethods(raw, "ServerNotification")
	if err != nil {
		t.Fatal(err)
	}
	callbackRaw := raw
	if _, err := parseSchemaMethods(callbackRaw, "ServerRequest"); err != nil {
		callbackRaw, err = os.ReadFile(filepath.Join(filepath.Dir(schemaPath), "ServerRequest.json"))
		if err != nil {
			t.Fatalf("read ServerRequest schema beside %s: %v", schemaPath, err)
		}
	}
	callbacks, err := parseSchemaMethods(callbackRaw, "ServerRequest")
	if err != nil {
		t.Fatal(err)
	}
	var parsed struct {
		Definitions map[string]struct {
			Required []string `json:"required"`
		} `json:"definitions"`
	}
	if err := json.Unmarshal(raw, &parsed); err != nil {
		t.Fatal(err)
	}
	for name, definition := range readStandaloneSchemas(t, filepath.Dir(schemaPath)) {
		if _, exists := parsed.Definitions[name]; !exists {
			parsed.Definitions[name] = definition
		}
	}
	classifyGenerated(t, requests, WireClientRequest)
	classifyGenerated(t, notifications, WireNotification)
	classifyGenerated(t, callbacks, WireServerRequest)
	enums, properties := readSchemaVocabulary(t, schemaPath)
	return ContractSurface{
		ClientRequests: requests, ServerNotifications: notifications, ServerRequests: callbacks,
		Enums: enums,
	}, generatedSchemaDocs{
		definitions: parsed.Definitions,
		properties:  properties,
	}
}

// readSchemaVocabulary collects, from the aggregate beside schemaPath and every
// other JSON file in its directory, the export's string enums and its property
// names (MADR 0236 D3.2 and D3.4). It reads the same files readGeneratedSurface
// reads for required fields, so the two cannot describe different exports.
func readSchemaVocabulary(t *testing.T, schemaPath string) (map[string][]string, map[string]struct{}) {
	t.Helper()
	dir := filepath.Dir(schemaPath)
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	sets := map[string]map[string]struct{}{}
	properties := map[string]struct{}{}
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			t.Fatal(err)
		}
		var doc map[string]any
		if err := json.Unmarshal(raw, &doc); err != nil {
			t.Fatalf("decode %s: %v", entry.Name(), err)
		}
		if title, ok := doc["title"].(string); ok && title != "" {
			addNamedEnum(sets, title, doc)
		}
		if definitions, ok := doc["definitions"].(map[string]any); ok {
			for name, node := range definitions {
				if m, ok := node.(map[string]any); ok {
					addNamedEnum(sets, name, m)
				}
			}
		}
		walkSchema(doc, sets, properties)
	}
	if len(sets) == 0 || len(properties) == 0 {
		t.Fatalf("no enums or no properties under %s: the export's layout changed and this reader needs updating", dir)
	}
	enums := make(map[string][]string, len(sets))
	for name, set := range sets {
		values := make([]string, 0, len(set))
		for value := range set {
			values = append(values, value)
		}
		sort.Strings(values)
		enums[name] = values
	}
	return enums, properties
}

// addNamedEnum records a definition that is a string enum, or a oneOf/anyOf
// whose every member is one. The second form is how 0.167.0 spells
// CommandExecutionApprovalKind, and codex's own Python generator flattens it the
// same way (_flatten_string_enum_one_of, MADR 0236 F15).
func addNamedEnum(sets map[string]map[string]struct{}, name string, node map[string]any) {
	if values, ok := stringEnum(node); ok {
		addValues(sets, name, values)
		return
	}
	for _, key := range []string{"oneOf", "anyOf"} {
		members, ok := node[key].([]any)
		if !ok || len(members) == 0 {
			continue
		}
		var all []string
		for _, member := range members {
			m, ok := member.(map[string]any)
			if !ok {
				return
			}
			values, ok := stringEnum(m)
			if !ok {
				return
			}
			all = append(all, values...)
		}
		addValues(sets, name, all)
		return
	}
}

// walkSchema records every property name, and every titled string enum nested
// anywhere, such as an item variant's "type" discriminator.
func walkSchema(node any, sets map[string]map[string]struct{}, properties map[string]struct{}) {
	switch n := node.(type) {
	case map[string]any:
		if props, ok := n["properties"].(map[string]any); ok {
			for name := range props {
				properties[name] = struct{}{}
			}
		}
		if title, ok := n["title"].(string); ok && title != "" {
			if values, ok := stringEnum(n); ok {
				addValues(sets, title, values)
			}
		}
		for _, child := range n {
			walkSchema(child, sets, properties)
		}
	case []any:
		for _, child := range n {
			walkSchema(child, sets, properties)
		}
	}
}

func stringEnum(node map[string]any) ([]string, bool) {
	raw, ok := node["enum"].([]any)
	if !ok || len(raw) == 0 {
		return nil, false
	}
	if _, hasProperties := node["properties"]; hasProperties {
		return nil, false
	}
	values := make([]string, 0, len(raw))
	for _, v := range raw {
		s, ok := v.(string)
		if !ok {
			return nil, false
		}
		values = append(values, s)
	}
	return values, true
}

func addValues(sets map[string]map[string]struct{}, name string, values []string) {
	set := sets[name]
	if set == nil {
		set = map[string]struct{}{}
		sets[name] = set
	}
	for _, value := range values {
		set[value] = struct{}{}
	}
}

// schemaPropertyNames is the sorted union of both exports' property names.
func schemaPropertyNames(docs ...generatedSchemaDocs) []string {
	union := map[string]struct{}{}
	for _, d := range docs {
		for name := range d.properties {
			union[name] = struct{}{}
		}
	}
	out := make([]string, 0, len(union))
	for name := range union {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// declaredExperimentalNotifications keeps the source scan's experimental
// notifications that the export declares. The scan also finds the two that
// export.rs strips from the JSON (rawResponseItem/completed and
// rawResponse/completed), and the manifest describes only what is declared.
func declaredExperimentalNotifications(t *testing.T, experimental ContractSurface, scanned map[string]struct{}) []string {
	t.Helper()
	declared := surfaceMethods(experimental, WireNotification)
	out := make([]string, 0, len(scanned))
	for method := range scanned {
		if _, ok := declared[method]; ok {
			out = append(out, method)
		} else {
			t.Logf("experimental notification %s is in the source but not in the export", method)
		}
	}
	sort.Strings(out)
	return out
}

// classifyGenerated marks each captured method with what this package does about
// it, derived from the package's own code (MADR 0163 D2) rather than from the
// hand-maintained switch this replaces. That switch named 32 client requests and
// zero server requests, so every one of the 21 server requests was recorded as
// typed_deferred while session.go answered nine of them on purpose (0163 F5), and
// the list drifted from the code silently because nothing compared the two.
func classifyGenerated(t *testing.T, entries []WireContract, kind WireKind) {
	t.Helper()
	callArgs, caseLabels := implementedMethods(t)
	for i := range entries {
		method := entries[i].Method
		entries[i].Classification = ClassificationTypedDeferred
		if kind == WireNotification {
			entries[i].Response = "none"
		} else {
			entries[i].Response = "typed"
		}
		switch {
		case method == "initialize" || method == "initialized":
			entries[i].Classification = ClassificationInternal
		case kind == WireNotification:
			// The routing decision itself, so it cannot disagree with runtime
			// behaviour the way a parallel list can.
			if notificationRouteFor(method) != notificationRouteUnknown {
				entries[i].Classification = ClassificationImplemented
			}
		case kind == WireServerRequest:
			if _, ok := caseLabels[method]; ok {
				entries[i].Classification = ClassificationImplemented
			}
		default:
			if _, ok := callArgs[method]; ok {
				entries[i].Classification = ClassificationImplemented
			}
		}
	}
}

func generatedCapabilities(stable, experimental ContractSurface) []CapabilityContract {
	// exposed lists the methods we choose to offer as capabilities. It carries no
	// stability claim of its own: stability is derived from the schema bundles
	// below. A hand-maintained stability list goes on calling a method
	// experimental long after upstream promotes it, which is exactly what happened
	// to thread/items/list and thread/turns/list — stable since #40673, still
	// emitted here as experimental with a fallback to the deprecated thread/read
	// (MADR 0163, amendment 2026-09-21).
	//
	// The split below is kept only because the two groups read differently to a
	// human; both halves land in the same map.
	exposed := map[string]SecurityClass{}
	for _, method := range []string{
		"initialize", "thread/list", "thread/read", "thread/loaded/list", "thread/start", "thread/resume", "thread/fork",
		"thread/name/set", "thread/metadata/update", "thread/section/move", "thread/archive", "thread/unarchive",
		"thread/unsubscribe", "thread/delete", "threadSection/list", "threadSection/create", "threadSection/update", "threadSection/delete",
		"turn/start", "turn/steer", "turn/interrupt", "thread/shellCommand", "command/exec", "command/exec/write",
		"command/exec/resize", "command/exec/terminate", "review/start", "thread/compact/start", "thread/approveGuardianDeniedAction",
		"thread/goal/set", "thread/goal/get", "thread/goal/clear", "model/list", "modelProvider/capabilities/read",
		"permissionProfile/list", "experimentalFeature/list", "experimentalFeature/enablement/set", "config/read", "config/value/write",
		"config/batchWrite", "configRequirements/read", "skills/list", "skills/extraRoots/set", "skills/config/write", "hooks/list",
		"app/list", "app/read", "app/installed", "marketplace/add", "marketplace/remove", "marketplace/upgrade", "plugin/list",
		"plugin/installed", "plugin/read", "plugin/skill/read", "plugin/install", "plugin/uninstall", "plugin/share/save",
		"plugin/share/updateTargets", "plugin/share/list", "plugin/share/checkout", "plugin/share/delete", "mcpServerStatus/list",
		"mcpServer/oauth/login", "config/mcpServer/reload", "mcpServer/resource/read", "mcpServer/tool/call", "fs/getMetadata",
		"fs/readDirectory", "fs/readFile", "fs/writeFile", "fs/createDirectory", "fs/copy", "fs/remove", "fs/watch", "fs/unwatch",
		"fuzzyFileSearch", "account/read", "account/login/start", "account/login/cancel", "account/logout", "account/rateLimits/read",
		"account/usage/read", "account/workspaceMessages/read", "account/rateLimitResetCredit/consume", "account/sendAddCreditsNudgeEmail",
		"externalAgentConfig/detect", "externalAgentConfig/import", "externalAgentConfig/import/recordHistory",
		"externalAgentConfig/import/readHistories", "feedback/upload",
	} {
		exposed[method] = securityForMethod(method)
	}
	for _, method := range []string{
		"server/diagnostics", "thread/search", "thread/searchOccurrences", "thread/turns/list", "thread/items/list",
		"thread/settings/update", "thread/queue/add", "thread/queue/list", "thread/queue/update", "thread/queue/delete",
		"thread/queue/reorder", "thread/queue/start", "thread/backgroundTerminals/clean", "thread/backgroundTerminals/list",
		"thread/backgroundTerminals/terminate", "thread/realtime/start", "thread/realtime/appendAudio", "thread/realtime/appendText",
		"thread/realtime/appendSpeech", "thread/realtime/stop", "thread/realtime/listVoices", "fuzzyFileSearch/sessionStart",
		"fuzzyFileSearch/sessionUpdate", "fuzzyFileSearch/sessionStop", "plugin/search", "collaborationMode/list",
		"project/list", "project/read", "project/create", "project/import", "project/update", "project/move", "project/delete",
		"environment/add", "environment/status", "environment/info", "process/spawn", "process/writeStdin", "process/resizePty", "process/kill",
	} {
		exposed[method] = securityForMethod(method)
	}

	// Stability is a property of the engine's schema, not of our opinion: a method
	// the stable bundle declares is stable, and a stable method needs no fallback
	// because there is no negotiation that can take it away. Only a method that
	// exists solely in the experimental bundle is experimental, and only those
	// carry a fallback.
	stableMethods := make(map[string]struct{}, len(stable.ClientRequests))
	for _, method := range stable.ClientRequests {
		stableMethods[method.Method] = struct{}{}
	}

	capabilities := make([]CapabilityContract, 0, len(exposed)+2)
	seen := make(map[string]struct{}, len(exposed))
	// The experimental bundle is a superset, but both are walked so that a method
	// present only in the stable bundle cannot be missed if that ever stops holding.
	for _, surface := range []ContractSurface{stable, experimental} {
		for _, method := range surface.ClientRequests {
			security, ok := exposed[method.Method]
			if !ok {
				continue
			}
			if _, duplicate := seen[method.Method]; duplicate {
				continue
			}
			seen[method.Method] = struct{}{}
			capability := CapabilityContract{
				ID:       CapabilityID("rpc:" + method.Method),
				Requires: []WireRequirement{{Kind: WireClientRequest, Method: method.Method}},
				Security: security,
			}
			if _, isStable := stableMethods[method.Method]; isStable {
				capability.Stability = StabilityStable
			} else {
				capability.Stability = StabilityExperimental
				capability.Fallback = fallbackForMethod(method.Method)
			}
			capabilities = append(capabilities, capability)
		}
	}
	capabilities = append(capabilities,
		CapabilityContract{ID: CapabilityThreadSource, Stability: StabilityStable, Requires: []WireRequirement{{Kind: WireClientRequest, Method: "thread/start"}, {Kind: WireClientRequest, Method: "thread/fork"}}, Security: SecurityWrite},
		CapabilityContract{ID: CapabilityThreadForkDeferGoal, Stability: StabilityExperimental, Requires: []WireRequirement{{Kind: WireClientRequest, Method: "thread/fork"}}, Security: SecurityWrite},
	)
	sort.Slice(capabilities, func(i, j int) bool { return capabilities[i].ID < capabilities[j].ID })
	return capabilities
}

// generatedFixtures builds one fixture per method. responses maps
// fixtureKey(kind, method) to the method's response type: from codex's source at
// capture time (sourceResponseTypes), and from the pinned fixtures in the live
// gate, which has no source tree (fixtureResponseTypes). A method absent from it
// gets "typed", which only a method the pin has never seen can do.
func generatedFixtures(stable, experimental ContractSurface, stableDocs, experimentalDocs generatedSchemaDocs, responses map[string]string) []ContractFixture {
	fixtures := make([]ContractFixture, 0, len(experimental.ClientRequests)+len(experimental.ServerNotifications)+len(experimental.ServerRequests))
	seen := make(map[string]struct{})
	appendSurface := func(stability Stability, surface ContractSurface, docs generatedSchemaDocs) {
		for kind, entries := range map[WireKind][]WireContract{
			WireClientRequest: surface.ClientRequests, WireNotification: surface.ServerNotifications, WireServerRequest: surface.ServerRequests,
		} {
			for _, entry := range entries {
				key := fixtureKey(kind, entry.Method)
				if _, ok := seen[key]; ok {
					continue
				}
				seen[key] = struct{}{}
				response := responses[key]
				switch {
				case kind == WireNotification:
					response = "none"
				case response == "":
					response = "typed"
				}
				fixtures = append(fixtures, ContractFixture{
					Kind: kind, Stability: stability, Method: entry.Method, ParamsSchema: entry.Params,
					ResponseSchema: response,
					RequiredParams: append([]string(nil), docs.definitions[entry.Params].Required...),
					RequiredResult: append([]string(nil), docs.definitions[response].Required...),
				})
			}
		}
	}
	appendSurface(StabilityStable, stable, stableDocs)
	appendSurface(StabilityExperimental, experimental, experimentalDocs)
	sort.Slice(fixtures, func(i, j int) bool {
		if fixtures[i].Kind == fixtures[j].Kind {
			return fixtures[i].Method < fixtures[j].Method
		}
		return fixtures[i].Kind < fixtures[j].Kind
	})
	return fixtures
}

func fixtureKey(kind WireKind, method string) string {
	return string(kind) + "\x00" + method
}

// fixtureResponseTypes recovers the pinned response types from a manifest's
// fixtures, for the live gate.
func fixtureResponseTypes(fixtures []ContractFixture) map[string]string {
	out := make(map[string]string, len(fixtures))
	for _, fixture := range fixtures {
		if fixture.Kind != WireNotification {
			out[fixtureKey(fixture.Kind, fixture.Method)] = fixture.ResponseSchema
		}
	}
	return out
}

// checkSourceResponseTypes fails the capture unless every client and server
// request the export declares has a declaration in codex's source, naming a type
// the export defines. It replaces a guess from the params name plus a
// hand-written override map, which had to grow by five entries at the 0.166.0
// re-pin after the tests failed (MADR 0236 F13, D3.1).
func checkSourceResponseTypes(t *testing.T, responses map[string]string, experimental ContractSurface, docs generatedSchemaDocs) {
	t.Helper()
	for kind, entries := range map[WireKind][]WireContract{
		WireClientRequest: experimental.ClientRequests, WireServerRequest: experimental.ServerRequests,
	} {
		for _, entry := range entries {
			response, ok := responses[fixtureKey(kind, entry.Method)]
			if !ok {
				t.Errorf("%s %s is in the export but has no declaration in common.rs", kind, entry.Method)
				continue
			}
			if _, defined := docs.definitions[response]; !defined {
				t.Errorf("%s %s: common.rs declares response %s, which the export does not define", kind, entry.Method, response)
			}
		}
	}
	if t.Failed() {
		t.FailNow()
	}
}

func readStandaloneSchemas(t *testing.T, dir string) map[string]struct {
	Required []string `json:"required"`
} {
	t.Helper()
	out := make(map[string]struct {
		Required []string `json:"required"`
	})
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			t.Fatal(err)
		}
		var schema struct {
			Title       string   `json:"title"`
			Required    []string `json:"required"`
			Definitions map[string]struct {
				Required []string `json:"required"`
			} `json:"definitions"`
		}
		if json.Unmarshal(raw, &schema) == nil && schema.Title != "" {
			out[schema.Title] = struct {
				Required []string `json:"required"`
			}{Required: schema.Required}
		}
		for name, definition := range schema.Definitions {
			if _, exists := out[name]; !exists {
				out[name] = definition
			}
		}
	}
	return out
}

func fallbackForMethod(method string) CapabilityID {
	switch method {
	case "thread/search":
		return CapabilityThreadList
	case "thread/searchOccurrences", "thread/turns/list", "thread/items/list":
		return CapabilityID("rpc:thread/read")
	case "thread/settings/update":
		return CapabilityID("rpc:turn/start")
	case "fuzzyFileSearch/sessionStart", "fuzzyFileSearch/sessionUpdate", "fuzzyFileSearch/sessionStop":
		return CapabilityID("rpc:fuzzyFileSearch")
	case "plugin/search":
		return CapabilityID("rpc:plugin/list")
	case "project/list", "project/read", "project/create", "project/import", "project/update", "project/move", "project/delete":
		return CapabilityThreadList
	default:
		return ""
	}
}

func securityForMethod(method string) SecurityClass {
	switch {
	case strings.Contains(method, "delete"), strings.Contains(method, "remove"), strings.Contains(method, "uninstall"), strings.Contains(method, "logout"):
		return SecurityDestructive
	case strings.Contains(method, "login"), strings.Contains(method, "oauth"), strings.Contains(method, "feedback"):
		return SecuritySecret
	case strings.HasPrefix(method, "command/"), strings.HasPrefix(method, "process/"), strings.Contains(method, "shellCommand"), strings.Contains(method, "backgroundTerminals"):
		return SecurityExecution
	case strings.Contains(method, "realtime"):
		return SecurityRealtime
	case strings.Contains(method, "/set"), strings.Contains(method, "/write"), strings.Contains(method, "/create"), strings.Contains(method, "/update"), strings.Contains(method, "/import"), strings.Contains(method, "/install"), strings.Contains(method, "/add"):
		return SecurityWrite
	default:
		return SecurityRead
	}
}

func sourceOnlyDelta(installedStable, installedExperimental, sourceStable, sourceExperimental ContractSurface) []string {
	var delta []string
	appendDelta := func(kind WireKind, installed, source []WireContract) {
		installedSet := make(map[string]struct{}, len(installed))
		for _, entry := range installed {
			installedSet[entry.Method] = struct{}{}
		}
		for _, entry := range source {
			if _, ok := installedSet[entry.Method]; !ok {
				delta = append(delta, string(kind)+":"+entry.Method)
			}
		}
	}
	appendDelta(WireClientRequest, installedExperimental.ClientRequests, sourceExperimental.ClientRequests)
	appendDelta(WireNotification, installedStable.ServerNotifications, sourceStable.ServerNotifications)
	sort.Strings(delta)
	return delta
}

func requiredEnv(t *testing.T, name string) string {
	t.Helper()
	value := os.Getenv(name)
	if value == "" {
		t.Fatalf("%s is required", name)
	}
	return value
}

func writeGeneratedJSON(t *testing.T, path string, value any) {
	t.Helper()
	raw, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	if err := os.WriteFile(path, raw, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %s (%d bytes)", path, len(raw))
}

func (d generatedSchemaDocs) String() string {
	return fmt.Sprintf("%d definitions", len(d.definitions))
}
